#include <stdio.h>
#include <stdlib.h>
#include <limits.h>
#include <errno.h>

int main(int argc, char *argv[]) {
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }

    char *end1, *end2;
    errno = 0;
    long a = strtol(argv[1], &end1, 10);
    long b = strtol(argv[2], &end2, 10);

    /* Bad input if conversion failed or extra characters remain */
    if (end1 == argv[1] || end2 == argv[2] || *end1 != '\0' || *end2 != '\0') {
        puts("BAD_INPUT");
        return 0;
    }

    /* Range check – absolute value must not exceed 1,000,000 */
    if (llabs(a) > 1000000L || llabs(b) > 1000000L) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    /* Work with absolute values */
    unsigned long ua = (a < 0) ? - (unsigned long)a : (unsigned long)a;
    unsigned long ub = (b < 0) ? - (unsigned long)b : (unsigned long)b;

    if (ua == 0 && ub == 0) {
        puts("gcd=0 lcm=0");
        return 0;
    }

    /* Euclidean algorithm for GCD */
    unsigned long x = ua, y = ub;
    while (y != 0) {
        unsigned long r = x % y;
        x = y;
        y = r;
    }
    unsigned long gcd = x;

    /* Compute LCM with overflow detection */
    unsigned long div = ua / gcd; // safe, gcd != 0
    if (div != 0 && ub > LLONG_MAX / div) {
        puts("OVERFLOW");
        return 0;
    }
    unsigned long lcm = div * ub;

    printf("gcd=%ld lcm=%ld\n", (long)gcd, (long)lcm);
    return 0;
}
